                           '    case Partial m share: m.amount * share\n'
                           'let label c =\n'
                           '  match c:\n'
                           '    case Core.Gbp: "GBP"\n'
                           '    case Core.Eur: "EUR"\n'
                           '    case Core.Other s: s\n',
