                          'import Left\n'
                          'import Right\n'
                          'let inv = Left.invoice [Core.gbp 2.0, Core.gbp 3.5]\n'
                          'let back = Right.Partial inv.total 0.5\n'
                          'let cur = Right.label inv.total.cur\n'
                          'type Ledger = { bill: Left.Invoice, refunds: List Right.Refund }\n'
                          'let ledger = Ledger { bill = inv, refunds = [back, Right.Full (Core.gbp 1.0)] }\n'
                          'let net = ledger.bill.total.amount - List.fold (fun acc r -> acc + Right.owed r) '
                          '0.0 ledger.refunds\n'
