@pytest.mark.parametrize("case", CASES, ids=[c["id"] for c in CASES])
def test_navigation_over_import_graphs(run, workdir, case):
    """CATCHES: cross-module type resolution, navigation, references, renames, symbols or
    member completion that differ from the reference server on a larger graph, or
    that read disk where an open buffer should win (or the reverse)."""
    S.check(run, workdir, case, __file__)
